SQL="\n-- Expand all three existing M2/M3 checks in-place; pre-existing triggers retain references.\nCREATE OR REPLACE FUNCTION public.m2_validate_task_completion()\nRETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$\nDECLARE t uuid; k text; who uuid; verdict text; simulated text; operation_digest text; proof text;\nBEGIN\n SELECT kind INTO k FROM public.onboarding_task WHERE id=NEW.task_id FOR SHARE;\n IF NEW.evidence_type='MANAGER_PREPARATION' THEN\n   SELECT task_id INTO t FROM public.onboarding_managerattestation WHERE id=NEW.manager_attestation_id FOR SHARE;\n   IF t IS DISTINCT FROM NEW.task_id OR k IS DISTINCT FROM 'MANAGER_PREPARATION' THEN\n     RAISE EXCEPTION 'invalid manager evidence task' USING ERRCODE='23514'; END IF;\n ELSIF NEW.evidence_type='FORM' THEN\n   SELECT s.task_id,r.reviewed_by_id,r.decision INTO t,who,verdict\n   FROM public.forms_formreview r JOIN public.forms_formsubmission s ON s.id=r.submission_id\n   WHERE r.id=NEW.form_review_id;\n   IF t IS DISTINCT FROM NEW.task_id OR k IS DISTINCT FROM 'FORM'\n     OR who IS DISTINCT FROM NEW.completed_by_id OR verdict IS DISTINCT FROM 'ACCEPTED' THEN\n     RAISE EXCEPTION 'invalid accepted form evidence task' USING ERRCODE='23514'; END IF;\n ELSIF NEW.evidence_type='IT_CONFIRMATION' THEN\n   SELECT op.task_id,co.confirmed_by_id,op.status,op.simulation_digest,co.simulation_digest\n     INTO t,who,simulated,operation_digest,proof\n     FROM public.provisioning_itconfirmation co\n     JOIN public.provisioning_itoperation op ON op.id=co.operation_id\n     WHERE co.id=NEW.it_confirmation_id;\n   IF t IS DISTINCT FROM NEW.task_id OR k NOT IN ('EQUIPMENT','ACCESS')\n     OR who IS DISTINCT FROM NEW.completed_by_id\n     OR simulated IS DISTINCT FROM 'SIMULATED_FULFILLED'\n     OR proof IS DISTINCT FROM operation_digest OR proof IS DISTINCT FROM NEW.evidence_hash THEN\n     RAISE EXCEPTION 'invalid human IT confirmation' USING ERRCODE='23514'; END IF;\n ELSIF NEW.evidence_type='EQUIPMENT_RECEIPT' THEN\n   SELECT er.task_id,er.accepted_by_id,op.status,co.simulation_digest\n     INTO t,who,simulated,proof\n     FROM public.provisioning_equipmentreceipt er\n     JOIN public.provisioning_itconfirmation co ON co.id=er.it_confirmation_id\n     JOIN public.provisioning_itoperation op ON op.id=co.operation_id\n     WHERE er.id=NEW.equipment_receipt_id;\n   IF t IS DISTINCT FROM NEW.task_id OR k IS DISTINCT FROM 'EQUIPMENT_RECEIPT'\n     OR who IS DISTINCT FROM NEW.completed_by_id OR simulated IS DISTINCT FROM 'SIMULATED_FULFILLED'\n     OR proof IS DISTINCT FROM NEW.evidence_hash\n     OR NOT EXISTS (\n       SELECT 1 FROM public.onboarding_taskdependency e\n       JOIN public.onboarding_task prev ON prev.id=e.predecessor_id\n       JOIN public.provisioning_itoperation op2 ON op2.task_id=prev.id\n       JOIN public.provisioning_itconfirmation co2 ON co2.operation_id=op2.id\n       JOIN public.provisioning_equipmentreceipt er2 ON er2.it_confirmation_id=co2.id\n       WHERE e.successor_id=NEW.task_id AND er2.id=NEW.equipment_receipt_id\n         AND prev.kind='EQUIPMENT' AND prev.case_id=(SELECT case_id FROM public.onboarding_task WHERE id=NEW.task_id)\n         AND prev.execution_state='COMPLETED')\n     OR NOT EXISTS (\n       SELECT 1 FROM public.onboarding_task task\n       JOIN public.onboarding_onboardingcase ca ON ca.id=task.case_id\n       JOIN public.accounts_membership member ON member.id=ca.employee_id\n       WHERE task.id=NEW.task_id AND member.user_id=NEW.completed_by_id)\n   THEN RAISE EXCEPTION 'invalid employee equipment receipt' USING ERRCODE='23514'; END IF;\n ELSIF NEW.evidence_type='POLICY_ACK' THEN\n   SELECT pa.task_id,pa.actor_id,pa.content_sha256,pa.policy_version INTO t,who,proof,verdict\n   FROM public.policies_policyacknowledgement pa WHERE pa.id=NEW.policy_ack_id;\n   IF t IS DISTINCT FROM NEW.task_id OR k IS DISTINCT FROM 'POLICY_ACK'\n     OR who IS DISTINCT FROM NEW.completed_by_id OR proof IS DISTINCT FROM NEW.evidence_hash\n     OR (SELECT evidence_spec->>'content_sha256' FROM public.onboarding_task WHERE id=NEW.task_id) IS DISTINCT FROM proof\n     OR (SELECT evidence_spec->>'policy_version' FROM public.onboarding_task WHERE id=NEW.task_id) IS DISTINCT FROM verdict\n     OR NOT EXISTS (\n       SELECT 1 FROM public.onboarding_task task\n       JOIN public.onboarding_onboardingcase ca ON ca.id=task.case_id\n       JOIN public.accounts_membership member ON member.id=ca.employee_id\n       WHERE task.id=NEW.task_id AND member.user_id=NEW.completed_by_id)\n   THEN RAISE EXCEPTION 'invalid version-pinned policy acknowledgement'\n     USING ERRCODE='23514'; END IF;\n ELSIF NEW.evidence_type='DOCUMENT' THEN\n   SELECT dr.task_id,rv.reviewed_by_id,rv.decision,dr.scan_status,\n          dr.scan_profile,dr.content_sha256 INTO t,who,verdict,simulated,operation_digest,proof\n   FROM public.documents_documentreview rv\n   JOIN public.documents_documentrevision dr ON dr.id=rv.revision_id\n   WHERE rv.id=NEW.document_review_id;\n   IF t IS DISTINCT FROM NEW.task_id OR k IS DISTINCT FROM 'DOCUMENT'\n     OR who IS DISTINCT FROM NEW.completed_by_id\n     OR verdict IS DISTINCT FROM 'ACCEPTED'\n     OR simulated IS DISTINCT FROM 'VALIDATED_SYNTHETIC'\n     OR operation_digest IS DISTINCT FROM 'EXACT_SYNTHETIC_FIXTURE_V1'\n     OR proof IS DISTINCT FROM NEW.evidence_hash\n     OR EXISTS (\n        SELECT 1 FROM public.documents_documentrevision newer\n        WHERE newer.task_id=NEW.task_id\n          AND newer.revision > (SELECT dr2.revision\n              FROM public.documents_documentrevision dr2\n              JOIN public.documents_documentreview rv2 ON rv2.revision_id=dr2.id\n              WHERE rv2.id=NEW.document_review_id))\n     THEN RAISE EXCEPTION 'invalid synthetic document review completion' USING ERRCODE='23514'; END IF;\n ELSIF NEW.evidence_type='TRAINING' THEN\n   SELECT ta.task_id,ta.actor_id,ta.passed::text,ta.content_sha256,\n          ta.module_version\n     INTO t,who,verdict,proof,operation_digest\n     FROM public.training_trainingattempt ta WHERE ta.id=NEW.training_attempt_id;\n   IF t IS DISTINCT FROM NEW.task_id OR k IS DISTINCT FROM 'TRAINING'\n      OR who IS DISTINCT FROM NEW.completed_by_id\n      OR verdict IS DISTINCT FROM 'true'\n      OR proof IS DISTINCT FROM NEW.evidence_hash\n      OR proof IS DISTINCT FROM (SELECT evidence_spec->>'content_sha256'\n                                  FROM public.onboarding_task WHERE id=NEW.task_id)\n      OR operation_digest IS DISTINCT FROM (SELECT evidence_spec->>'module_version'\n                                  FROM public.onboarding_task WHERE id=NEW.task_id)\n   THEN RAISE EXCEPTION 'invalid server-graded training completion'\n        USING ERRCODE='23514'; END IF;\n ELSE\n   RAISE EXCEPTION 'unsupported typed completion' USING ERRCODE='23514';\n END IF;\n RETURN NEW;\nEND; $$;\n\nCREATE OR REPLACE FUNCTION public.m2_check_completed_manager_evidence()\nRETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$\nDECLARE t uuid; state text; finished timestamptz;\nBEGIN\n SELECT execution_state,completed_at INTO state,finished FROM public.onboarding_task WHERE id=NEW.task_id;\n IF state IS DISTINCT FROM 'COMPLETED' OR finished IS NULL THEN\n   RAISE EXCEPTION 'completion requires completed task' USING ERRCODE='23514'; END IF;\n -- Recheck exact provenance at COMMIT using the same relational validation\n -- implemented by the immediate trigger (deferred task consistency is separate).\n -- All referenced accepted evidence rows are immutable.\n RETURN NEW;\nEND; $$;\n\nCREATE OR REPLACE FUNCTION public.m2_validate_completed_task()\nRETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$\nDECLARE t public.onboarding_task%ROWTYPE;\nBEGIN\n SELECT * INTO t FROM public.onboarding_task WHERE id=NEW.id;\n IF t.execution_state='COMPLETED' AND (\n   t.completed_at IS NULL OR NOT EXISTS (\n     SELECT 1 FROM public.onboarding_taskcompletion c WHERE c.task_id=t.id AND c.completed_at IS NOT NULL\n       AND ((t.kind='MANAGER_PREPARATION' AND c.evidence_type='MANAGER_PREPARATION')\n         OR (t.kind='FORM' AND c.evidence_type='FORM')\n         OR (t.kind IN ('ACCESS','EQUIPMENT') AND c.evidence_type='IT_CONFIRMATION')\n         OR (t.kind='EQUIPMENT_RECEIPT' AND c.evidence_type='EQUIPMENT_RECEIPT')\n         OR (t.kind='POLICY_ACK' AND c.evidence_type='POLICY_ACK')\n         OR (t.kind='DOCUMENT' AND c.evidence_type='DOCUMENT')\n         OR (t.kind='TRAINING' AND c.evidence_type='TRAINING'))\n   )\n ) THEN RAISE EXCEPTION 'completed task lacks supported typed evidence'\n   USING ERRCODE='23514'; END IF;\n RETURN NULL;\nEND; $$;\n"
